def reward_function(params):
    if (
        not params['all_wheels_on_track']
        or params.get('is_offtrack', False)
        or params.get('is_crashed', False)
    ):
        return 0.001
    x, y = params['x'], params['y']
    b = float('inf')
    k, f = 0, 0.0
    n = len(RACING_LINE)
    for i, (ax, ay) in enumerate(RACING_LINE):
        bx, by = RACING_LINE[(i + 1) % n]
        dx, dy = bx - ax, by - ay
        t = max(
            0.0, min(
                1.0,
                ((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)
            )
        )
        d = (x - ax - t * dx) ** 2 + (y - ay - t * dy) ** 2
        if d < b:
            b, k, f = d, i, t
    ax, ay = RACING_LINE[k]
    bx, by = RACING_LINE[(k + 1) % n]
    tx, ty = ax + f * (bx - ax), ay + f * (by - ay)
    r = 0.60
    for _ in range(n):
        length = math.hypot(bx - tx, by - ty)
        if length >= r:
            tx += r * (bx - tx) / length
            ty += r * (by - ty) / length
            break
        r -= length
        tx, ty = bx, by
        k = (k + 1) % n
        bx, by = RACING_LINE[(k + 1) % n]
    h = math.radians(params['heading'])
    error = math.atan2(ty - y, tx - x) - h
    c = max(0.0, math.cos(error)) ** 2
    w = max(0.01, params['track_width'])
    q = math.exp(-b / max(0.1, 0.35 * w) ** 2)
    wp = params['waypoints']
    prev, nxt = params['closest_waypoints']
    ax, ay = wp[prev]
    bx, by = wp[nxt]
    dx, dy = bx - ax, by - ay
    cross = dx * (y - ay) - dy * (x - ax)
    sign = 1.0 if cross >= 0.0 else -1.0
    o = max(0.0, sign * math.sin(h - math.atan2(dy, dx)))
    g = 0.5 * w - params['distance_from_center']
    z = max(0.0, min(1.0, 1.0 - g / (0.20 * w)))
    s = 1.0 - 0.85 * z * min(1.0, o / 0.35)
    v = min(1.0, max(0.0, params['speed']) / 2.0)
    return float(
        0.001 + c * (0.2 + 0.8 * q)
        * (0.7 + 0.3 * v) * s
    )
